pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 seed) public {
        // The bug manifests after a single loss, so we need at least one call where random != 0.
        // To drive the contract, we make one play. We use a fuzzed seed to influence block.timestamp/difficulty
        // to get a loss (odd result). We don't hardcode a particular timestamp; we let the fuzzer search.
        // The rule: after a loss (pot > 0), pot must equal TICKET_AMOUNT (since only one play).
        // If the play wins, pot == 0. We assert: pot == 0 || pot == TICKET_AMOUNT.
        // The mutant always resets pot to 0, so after a loss pot will be 0, violating the rule.
        vm.deal(address(this), 10 ether);
        // Set block.timestamp and block.difficulty based on seed to make the randomness deterministic
        // but variable. The fuzzer will try different seeds until it finds one that yields a loss.
        vm.warp(uint256(keccak256(abi.encode(seed))) % type(uint40).max);
        vm.roll(uint256(keccak256(abi.encode(seed + 1))) % type(uint40).max);

        try c.play{value: 10}() {
            // success
        } catch {
            // If it reverts, the pot doesn't change; we can still assert.
        }

        // After one play, pot is either 0 (win) or TICKET_AMOUNT (loss). The mutant resets to 0 always.
        uint pot = c.pot();
        assertTrue(pot == 0 || pot == 10);
    }
}

